window.VP_ENRICH = {"abandon":{"id":1,"word":"Abandon","uzbek":"tark etmoq, voz kechmoq","type":"word","explanation":"To leave something or someone permanently, or stop doing something.","izoh":"Biror narsani yoki kishini butunlay tark etish yoki biror ishni bajarishni to‘xtatish.","example":"They had to abandon their plans because of the bad weather.","translation":"Ular yomon ob-havo sababli rejalaridan voz kechishga majbur bo‘lishdi.","collocations":"abandon a plan / abandon a project / abandon hope"},"ability":{"id":2,"word":"Ability","uzbek":"qobiliyat, salohiyat","type":"word","explanation":"The skill or power to do something successfully.","izoh":"Biror ishni muvaffaqiyatli bajarish uchun zarur bo‘lgan mahorat yoki salohiyat.","example":"She has the ability to solve difficult problems quickly.","translation":"U murakkab muammolarni tez hal qilish qobiliyatiga ega.","collocations":"natural ability / communication ability / ability to learn"},"absorb":{"id":3,"word":"Absorb","uzbek":"singdirmoq, o‘zlashtirmoq","type":"word","explanation":"To take in information, liquid, or energy.","izoh":"Ma’lumot, suyuqlik yoki energiyani o‘ziga singdirish yoki qabul qilish.","example":"Students need time to absorb new information.","translation":"O‘quvchilarga yangi ma’lumotlarni o‘zlashtirish uchun vaqt kerak.","collocations":"absorb information / absorb water / absorb knowledge"},"abstract":{"id":4,"word":"Abstract","uzbek":"mavhum, nazariy","type":"word","explanation":"Existing as an idea rather than as a physical object.","izoh":"Jismoniy shaklga ega bo‘lmay, fikr yoki tushuncha sifatida mavjud bo‘lgan.","example":"The teacher explained an abstract concept using simple examples.","translation":"O‘qituvchi mavhum tushunchani oddiy misollar yordamida tushuntirdi.","collocations":"abstract idea / abstract concept / abstract thinking"},"academic":{"id":5,"word":"Academic","uzbek":"akademik, ilmiy, o‘quvga oid","type":"word","explanation":"Related to education, studying, or scholarly work.","izoh":"Ta’lim, o‘qish yoki ilmiy faoliyat bilan bog‘liq.","example":"He received an academic award for his excellent results.","translation":"U a’lo natijalari uchun akademik mukofot oldi.","collocations":"academic achievement / academic year / academic research"},"access":{"id":6,"word":"Access","uzbek":"foydalanish imkoniyati, kirish","type":"word","explanation":"The opportunity or right to use or enter something.","izoh":"Biror narsadan foydalanish yoki muayyan joyga kirish imkoniyati yoxud huquqi.","example":"Students have access to free online learning materials.","translation":"O‘quvchilar bepul onlayn ta’lim materiallaridan foydalanish imkoniyatiga ega.","collocations":"internet access / gain access / access information"},"accompany":{"id":7,"word":"Accompany","uzbek":"hamrohlik qilmoq, birga bormoq","type":"word","explanation":"To go somewhere with someone, or happen together with something.","izoh":"Kimdir bilan biror joyga birga borish yoki biror hodisa bilan birga sodir bo‘lish.","example":"My brother accompanied me to the hospital.","translation":"Akam men bilan kasalxonaga bordi.","collocations":"accompany a friend / accompany someone home / accompany a report"},"accomplish":{"id":8,"word":"Accomplish","uzbek":"amalga oshirmoq, uddalamoq","type":"word","explanation":"To succeed in doing something through effort or skill.","izoh":"Harakat yoki mahorat orqali biror ishni muvaffaqiyatli bajarish.","example":"She accomplished all her goals before the end of the year.","translation":"U yil oxirigacha barcha maqsadlariga erishdi.","collocations":"accomplish a task / accomplish a goal / accomplish a mission"},"accurate":{"id":9,"word":"Accurate","uzbek":"aniq, to‘g‘ri","type":"word","explanation":"Correct and free from mistakes.","izoh":"Xatosiz, haqiqatga mos va ishonchli bo‘lgan.","example":"Please make sure the information is accurate before publishing it.","translation":"Ma’lumotni e’lon qilishdan oldin uning to‘g‘riligiga ishonch hosil qiling.","collocations":"accurate information / accurate results / highly accurate"},"achievement":{"id":10,"word":"Achievement","uzbek":"yutuq, muvaffaqiyat","type":"word","explanation":"Something important that you have successfully completed through effort.","izoh":"Mehnat va harakat natijasida muvaffaqiyatli amalga oshirilgan muhim ish.","example":"Learning a foreign language is a great achievement.","translation":"Chet tilini o‘rganish katta yutuqdir.","collocations":"personal achievement / academic achievement / major achievement"},"acknowledge":{"id":11,"word":"Acknowledge","uzbek":"tan olmoq, e’tirof etmoq","type":"word","explanation":"To accept that something is true or recognize someone's efforts.","izoh":"Biror narsaning haqiqat ekanini qabul qilish yoki kimningdir mehnatini e’tirof etish.","example":"The manager acknowledged her hard work.","translation":"Menejer uning mehnatini e’tirof etdi.","collocations":"acknowledge a mistake / acknowledge someone's efforts / publicly acknowledge"},"acquire":{"id":12,"word":"Acquire","uzbek":"qo‘lga kiritmoq, egallamoq","type":"word","explanation":"To gain or obtain something through effort or experience.","izoh":"Harakat, tajriba yoki o‘rganish orqali biror narsaga ega bo‘lish.","example":"You can acquire useful skills through regular practice.","translation":"Muntazam mashq qilish orqali foydali ko‘nikmalarga ega bo‘lishingiz mumkin.","collocations":"acquire knowledge / acquire skills / acquire experience"},"adapt":{"id":13,"word":"Adapt","uzbek":"moslashmoq, moslashtirmoq","type":"word","explanation":"To change your behaviour or something else to suit a new situation.","izoh":"Yangi vaziyatga mos kelishi uchun xatti-harakatni yoki biror narsani o‘zgartirish.","example":"It took me a few weeks to adapt to my new school.","translation":"Yangi maktabimga moslashishim uchun bir necha hafta kerak bo‘ldi.","collocations":"adapt to change / adapt quickly / adapt a method"},"additional":{"id":14,"word":"Additional","uzbek":"qo‘shimcha","type":"word","explanation":"Extra or added to what already exists.","izoh":"Mavjud narsaga qo‘shilgan yoki undan ortiq bo‘lgan.","example":"We need additional information before making a decision.","translation":"Qaror qabul qilishdan oldin bizga qo‘shimcha ma’lumot kerak.","collocations":"additional information / additional cost / additional support"},"adequate":{"id":15,"word":"Adequate","uzbek":"yetarli, munosib","type":"word","explanation":"Enough or satisfactory for a particular purpose.","izoh":"Muayyan maqsad uchun yetarli yoki talabga javob beradigan.","example":"The hotel provided adequate facilities for its guests.","translation":"Mehmonxona mehmonlari uchun yetarli qulayliklarni taqdim etdi.","collocations":"adequate preparation / adequate resources / adequate amount"},"adjust":{"id":16,"word":"Adjust","uzbek":"moslashtirmoq, sozlamoq","type":"word","explanation":"To change something slightly so that it is suitable or works better.","izoh":"Biror narsani mos kelishi yoki yaxshiroq ishlashi uchun biroz o‘zgartirish.","example":"I had to adjust the screen brightness to read comfortably.","translation":"Bemalol o‘qishim uchun ekran yorqinligini sozlashimga to‘g‘ri keldi.","collocations":"adjust the settings / adjust to a new routine / make an adjustment"},"admire":{"id":17,"word":"Admire","uzbek":"qoyil qolmoq, hurmat qilmoq","type":"word","explanation":"To respect someone or something because of their qualities or achievements.","izoh":"Kimningdir fazilatlari yoki yutuqlari sababli unga hurmat bilan qarash.","example":"I admire people who remain calm under pressure.","translation":"Bosim ostida ham xotirjam qoladigan insonlarga qoyil qolaman.","collocations":"admire someone's courage / deeply admire / admire a view"},"admission":{"id":18,"word":"Admission","uzbek":"kirish, qabul; tan olish","type":"word","explanation":"Permission to enter a place or the act of accepting that something is true.","izoh":"Biror joyga kirishga ruxsat berish yoki biror narsani haqiqat deb tan olish.","example":"Admission to the museum is free on Sundays.","translation":"Yakshanba kunlari muzeyga kirish bepul.","collocations":"university admission / admission fee / an admission of guilt"},"adopt":{"id":19,"word":"Adopt","uzbek":"qabul qilmoq, farzandlikka olmoq","type":"word","explanation":"To start using an idea or method, or legally take a child into your family.","izoh":"Biror g‘oya yoki usuldan foydalanishni boshlash yoki bolani qonuniy ravishda oilaga qabul qilish.","example":"Our school decided to adopt a new teaching method.","translation":"Maktabimiz yangi o‘qitish usulini qabul qilishga qaror qildi.","collocations":"adopt a policy / adopt a child / adopt a new approach"},"advance":{"id":20,"word":"Advance","uzbek":"rivojlanmoq, oldinga siljimoq; taraqqiyot","type":"word","explanation":"To move forward or make progress; a development or improvement.","izoh":"Oldinga harakatlanish yoki rivojlanish; taraqqiyot yoki yaxshilanish.","example":"Technology continues to advance rapidly.","translation":"Texnologiya jadal sur’atlarda rivojlanishda davom etmoqda.","collocations":"advance rapidly / scientific advances / in advance"},"advantage":{"id":21,"word":"Advantage","uzbek":"afzallik, ustunlik","type":"word","explanation":"A condition that makes someone or something more successful than others.","izoh":"Kimnidir yoki nimanidir boshqalarga nisbatan muvaffaqiyatliroq qiladigan jihat.","example":"Speaking two languages gives you an advantage at work.","translation":"Ikki tilda gaplasha olish ishda sizga ustunlik beradi.","collocations":"competitive advantage / have an advantage / take advantage of"},"adventure":{"id":22,"word":"Adventure","uzbek":"sarguzasht","type":"word","explanation":"An exciting or unusual experience, often involving some risk.","izoh":"Ko‘pincha ma’lum xavfni o‘z ichiga oladigan hayajonli yoki noodatiy tajriba.","example":"Their trip to the mountains became an unforgettable adventure.","translation":"Ularning tog‘larga safari unutilmas sarguzashtga aylandi.","collocations":"go on an adventure / exciting adventure / adventure travel"},"advertise":{"id":23,"word":"Advertise","uzbek":"reklama qilmoq, e’lon bermoq","type":"word","explanation":"To tell people about a product or service to encourage them to buy or use it.","izoh":"Odamlarni mahsulot yoki xizmatni sotib olishga undash uchun u haqida ma’lumot tarqatish.","example":"The company advertises its products on social media.","translation":"Kompaniya mahsulotlarini ijtimoiy tarmoqlarda reklama qiladi.","collocations":"advertise a product / advertise online / advertise a vacancy"},"advice":{"id":24,"word":"Advice","uzbek":"maslahat","type":"word","explanation":"An opinion or suggestion about what someone should do.","izoh":"Kimdir nima qilishi kerakligi haqidagi fikr yoki tavsiya.","example":"My teacher gave me useful advice about preparing for the exam.","translation":"O‘qituvchim imtihonga tayyorlanish haqida menga foydali maslahat berdi.","collocations":"give advice / follow advice / practical advice"},"affect":{"id":25,"word":"Affect","uzbek":"ta’sir qilmoq","type":"word","explanation":"To produce a change in someone or something.","izoh":"Kimdir yoki nimadadir o‘zgarish yuzaga keltirmoq.","example":"Lack of sleep can affect your concentration.","translation":"Uyqu yetishmasligi diqqatni jamlashingizga ta’sir qilishi mumkin.","collocations":"affect health / strongly affect / negatively affect"},"afford":{"id":26,"word":"Afford","uzbek":"qurbi yetmoq, imkoniyati bo‘lmoq","type":"word","explanation":"To have enough money, time, or ability to do something.","izoh":"Biror ishni bajarish uchun yetarli pul, vaqt yoki imkoniyatga ega bo‘lmoq.","example":"We cannot afford to buy a new laptop this month.","translation":"Bu oy yangi noutbuk sotib olishga qurbi yetmaydi.","collocations":"afford a car / cannot afford to wait / easily afford"},"agency":{"id":27,"word":"Agency","uzbek":"agentlik, tashkilot","type":"word","explanation":"A business or organization that provides a particular service.","izoh":"Muayyan xizmatni ko‘rsatadigan tashkilot yoki korxona.","example":"She found her new job through a recruitment agency.","translation":"U yangi ishini ishga joylashtirish agentligi orqali topdi.","collocations":"travel agency / government agency / advertising agency"},"agenda":{"id":28,"word":"Agenda","uzbek":"kun tartibi, reja","type":"word","explanation":"A list of subjects or tasks to be discussed or completed.","izoh":"Muhokama qilinishi yoki bajarilishi kerak bo‘lgan mavzular va vazifalar ro‘yxati.","example":"The manager shared the meeting agenda by email.","translation":"Menejer yig‘ilish kun tartibini elektron pochta orqali yubordi.","collocations":"meeting agenda / set an agenda / follow the agenda"},"aggressive":{"id":29,"word":"Aggressive","uzbek":"tajovuzkor, keskin","type":"word","explanation":"Behaving in an angry or forceful way, sometimes ready to attack.","izoh":"Jahldor yoki kuch ishlatishga moyil tarzda harakat qiladigan.","example":"His aggressive behaviour made the discussion uncomfortable.","translation":"Uning tajovuzkor xatti-harakati muhokamani noqulay qildi.","collocations":"aggressive behaviour / aggressive approach / aggressive marketing"},"agreement":{"id":30,"word":"Agreement","uzbek":"kelishuv, bitim, rozilik","type":"word","explanation":"A situation in which people share the same opinion or make a formal arrangement.","izoh":"Odamlarning bir fikrga kelishi yoki rasmiy kelishuv tuzishi.","example":"Both companies signed an agreement last week.","translation":"Ikkala kompaniya o‘tgan hafta kelishuvni imzoladi.","collocations":"reach an agreement / sign an agreement / mutual agreement"},"agriculture":{"id":31,"word":"Agriculture","uzbek":"qishloq xo‘jaligi","type":"word","explanation":"The practice of growing crops and keeping animals for food and other products.","izoh":"Oziq-ovqat va boshqa mahsulotlar olish uchun ekin yetishtirish va hayvon boqish faoliyati.","example":"Agriculture provides jobs for many people in rural areas.","translation":"Qishloq xo‘jaligi qishloq joylarda ko‘plab odamlarni ish bilan ta’minlaydi.","collocations":"modern agriculture / agricultural production / agriculture industry"},"aim":{"id":32,"word":"Aim","uzbek":"maqsad, intilmoq","type":"word","explanation":"A purpose or result that someone plans to achieve; to try to achieve it.","izoh":"Erishish rejalashtirilgan maqsad yoki natija; unga erishishga harakat qilmoq.","example":"Our main aim is to improve students' speaking skills.","translation":"Bizning asosiy maqsadimiz o‘quvchilarning gapirish ko‘nikmalarini yaxshilashdir.","collocations":"main aim / aim to improve / achieve an aim"},"alarm":{"id":33,"word":"Alarm","uzbek":"signal, xavotir; ogohlantirmoq","type":"word","explanation":"A warning sound or device, or a feeling of fear and concern.","izoh":"Ogohlantiruvchi ovoz yoki qurilma, yoxud qo‘rquv va tashvish hissi.","example":"The fire alarm woke everyone in the building.","translation":"Yong‘in signalizatsiyasi binodagi hammani uyg‘otdi.","collocations":"fire alarm / raise the alarm / alarm system"},"alter":{"id":34,"word":"Alter","uzbek":"o‘zgartirmoq","type":"word","explanation":"To change something, usually slightly, without completely replacing it.","izoh":"Biror narsani butunlay almashtirmasdan, odatda biroz o‘zgartirish.","example":"We had to alter our travel plans at the last minute.","translation":"So‘nggi daqiqada sayohat rejalarimizni o‘zgartirishimizga to‘g‘ri keldi.","collocations":"alter a decision / slightly alter / alter the design"},"alternative":{"id":35,"word":"Alternative","uzbek":"muqobil, boshqa variant","type":"word","explanation":"An option that can be chosen instead of another.","izoh":"Boshqa variant o‘rniga tanlash mumkin bo‘lgan yo‘l yoki imkoniyat.","example":"If the bus is full, we can take an alternative route.","translation":"Agar avtobus to‘la bo‘lsa, boshqa yo‘nalishdan foydalanishimiz mumkin.","collocations":"alternative solution / alternative energy / consider an alternative"},"ambition":{"id":36,"word":"Ambition","uzbek":"intilish, katta maqsad","type":"word","explanation":"A strong desire to achieve something important.","izoh":"Muhim biror narsaga erishish istagining kuchli bo‘lishi.","example":"Her ambition is to become a successful doctor.","translation":"Uning katta maqsadi muvaffaqiyatli shifokor bo‘lish.","collocations":"career ambition / strong ambition / achieve an ambition"},"amuse":{"id":37,"word":"Amuse","uzbek":"kuldir­moq, ko‘nglini ochmoq","type":"word","explanation":"To make someone laugh or feel entertained.","izoh":"Kimnidir kuldirish yoki uning vaqtini maroqli o‘tkazishiga sabab bo‘lish.","example":"The children's jokes amused everyone at dinner.","translation":"Bolalarning hazillari kechki ovqat paytida hammani kuldirdi.","collocations":"amuse the audience / highly amusing / amuse yourself"},"analyse":{"id":38,"word":"Analyse","uzbek":"tahlil qilmoq","type":"word","explanation":"To examine something carefully in order to understand it.","izoh":"Biror narsani tushunish uchun uni sinchiklab o‘rganish.","example":"We need to analyse the results before changing the plan.","translation":"Rejani o‘zgartirishdan oldin natijalarni tahlil qilishimiz kerak.","collocations":"analyse data / analyse a problem / carefully analyse"},"analysis":{"id":39,"word":"Analysis","uzbek":"tahlil","type":"word","explanation":"A detailed examination of something in order to understand it.","izoh":"Biror narsani tushunish maqsadida uni batafsil o‘rganish jarayoni.","example":"The analysis showed that most customers prefer online payments.","translation":"Tahlil ko‘pchilik mijozlar onlayn to‘lovlarni afzal ko‘rishini ko‘rsatdi.","collocations":"detailed analysis / data analysis / carry out an analysis"},"announce":{"id":40,"word":"Announce","uzbek":"e’lon qilmoq, xabar bermoq","type":"word","explanation":"To make information known publicly or officially.","izoh":"Ma’lumotni ommaga yoki rasmiy ravishda ma’lum qilish.","example":"The school will announce the exam results tomorrow.","translation":"Maktab ertaga imtihon natijalarini e’lon qiladi.","collocations":"announce a decision / officially announce / announce the results"},"annual":{"id":41,"word":"Annual","uzbek":"yillik, har yili bo‘ladigan","type":"word","explanation":"Happening once every year or relating to a year.","izoh":"Har yili bir marta sodir bo‘ladigan yoki bir yilga tegishli.","example":"Our company holds an annual meeting in December.","translation":"Kompaniyamiz dekabr oyida yillik yig‘ilish o‘tkazadi.","collocations":"annual report / annual income / annual meeting"},"anxiety":{"id":42,"word":"Anxiety","uzbek":"xavotir, bezovtalik","type":"word","explanation":"A feeling of worry or nervousness about something uncertain.","izoh":"Noaniq vaziyat yoki hodisa haqida tashvishlanish va asabiylashish hissi.","example":"Many students experience anxiety before important exams.","translation":"Ko‘plab o‘quvchilar muhim imtihonlardan oldin xavotirni his qilishadi.","collocations":"feel anxiety / reduce anxiety / anxiety disorder"},"apparent":{"id":43,"word":"Apparent","uzbek":"yaqqol, ko‘rinib turgan","type":"word","explanation":"Easy to notice or understand; seeming to be true.","izoh":"Sezish yoki tushunish oson bo‘lgan; haqiqatdek ko‘rinadigan.","example":"It became apparent that we needed more time.","translation":"Bizga ko‘proq vaqt kerakligi ayon bo‘ldi.","collocations":"apparent reason / become apparent / apparently obvious"},"appeal":{"id":44,"word":"Appeal","uzbek":"murojaat, joziba; murojaat qilmoq","type":"word","explanation":"A serious request, or the quality of being attractive or interesting.","izoh":"Jiddiy iltimos yoki biror narsaning jozibador va qiziqarli bo‘lish xususiyati.","example":"The idea of working abroad appeals to many young people.","translation":"Chet elda ishlash g‘oyasi ko‘plab yoshlarga ma’qul keladi.","collocations":"make an appeal / appeal to customers / wide appeal"},"approach":{"id":45,"word":"Approach","uzbek":"yondashuv, yaqinlashmoq","type":"word","explanation":"A way of dealing with a situation or problem; to move closer.","izoh":"Vaziyat yoki muammoni hal qilish usuli; yaqinroq kelmoq.","example":"We need a different approach to teaching grammar.","translation":"Grammatikani o‘qitishda bizga boshqacha yondashuv kerak.","collocations":"practical approach / approach a problem / new approach"},"appropriate":{"id":46,"word":"Appropriate","uzbek":"mos, munosib","type":"word","explanation":"Suitable or right for a particular situation or purpose.","izoh":"Muayyan vaziyat yoki maqsad uchun mos va to‘g‘ri bo‘lgan.","example":"Please wear appropriate clothes for the interview.","translation":"Iltimos, suhbat uchun mos kiyim kiying.","collocations":"appropriate behaviour / appropriate response / highly appropriate"},"approval":{"id":47,"word":"Approval","uzbek":"ma’qullash, rozilik","type":"word","explanation":"The feeling or statement that something is acceptable or good.","izoh":"Biror narsani maqbul yoki yaxshi deb hisoblash hissi yoki bayonoti.","example":"We need the manager's approval before spending the money.","translation":"Pulni sarflashdan oldin menejerning roziligini olishimiz kerak.","collocations":"give approval / seek approval / official approval"},"approve":{"id":48,"word":"Approve","uzbek":"ma’qullamoq, tasdiqlamoq","type":"word","explanation":"To officially accept something or believe that it is good.","izoh":"Biror narsani rasman qabul qilish yoki uni yaxshi deb hisoblash.","example":"The director approved our proposal yesterday.","translation":"Direktor kecha taklifimizni ma’qulladi.","collocations":"approve a request / approve a plan / fully approve"},"approximately":{"id":49,"word":"Approximately","uzbek":"taxminan","type":"word","explanation":"Used to show that a number or amount is not exact.","izoh":"Son yoki miqdor aniq emas, taxminiy ekanini bildirish uchun ishlatiladi.","example":"The journey takes approximately three hours.","translation":"Safar taxminan uch soat davom etadi.","collocations":"approximately equal / approximately ten people / approximately the same"},"argue":{"id":50,"word":"Argue","uzbek":"bahslashmoq, tortishmoq","type":"word","explanation":"To disagree with someone, sometimes angrily, or give reasons for an opinion.","izoh":"Kim bilandir, ba’zan jahllanib, kelishmovchilik bildirish yoki fikrni dalillar bilan asoslash.","example":"My friends often argue about which film to watch.","translation":"Do‘stlarim qaysi filmni ko‘rish haqida tez-tez bahslashishadi.","collocations":"argue about something / argue with someone / strongly argue"},"argument":{"id":51,"word":"Argument","uzbek":"bahs, dalil","type":"word","explanation":"A disagreement between people, or a reason supporting an opinion.","izoh":"Odamlar o‘rtasidagi kelishmovchilik yoki fikrni qo‘llab-quvvatlovchi sabab.","example":"They had an argument about money.","translation":"Ular pul masalasida tortishib qolishdi.","collocations":"have an argument / strong argument / convincing argument"},"arise":{"id":52,"word":"Arise","uzbek":"yuzaga kelmoq, paydo bo‘lmoq","type":"word","explanation":"To happen or begin to exist, especially when a problem occurs.","izoh":"Ayniqsa muammo yuz berganda, sodir bo‘lmoq yoki paydo bo‘lmoq.","example":"If any problems arise, contact the support team.","translation":"Agar biror muammo yuzaga kelsa, yordam xizmatiga murojaat qiling.","collocations":"problems arise / arise from / opportunity arises"},"arrange":{"id":53,"word":"Arrange","uzbek":"tashkil qilmoq, tartibga solmoq","type":"word","explanation":"To organize or plan something, or put things in a particular order.","izoh":"Biror narsani rejalashtirish yoki tashkil qilish, yoxud narsalarni muayyan tartibda joylashtirish.","example":"I arranged a meeting with my English teacher.","translation":"Men ingliz tili o‘qituvchim bilan uchrashuv tashkil qildim.","collocations":"arrange a meeting / arrange transport / arrange flowers"},"arrangement":{"id":54,"word":"Arrangement","uzbek":"kelishuv, tartib, tashkiliy reja","type":"word","explanation":"A plan or agreement about how something will happen.","izoh":"Biror ish qanday amalga oshishi haqidagi reja yoki kelishuv.","example":"We made travel arrangements two weeks before the holiday.","translation":"Ta’tildan ikki hafta oldin sayohat rejasini tuzdik.","collocations":"make arrangements / seating arrangement / travel arrangements"},"artificial":{"id":55,"word":"Artificial","uzbek":"sun’iy","type":"word","explanation":"Made by people rather than occurring naturally.","izoh":"Tabiiy ravishda paydo bo‘lmay, insonlar tomonidan yaratilgan.","example":"The room was decorated with artificial flowers.","translation":"Xona sun’iy gullar bilan bezatilgan edi.","collocations":"artificial intelligence / artificial light / artificial materials"},"aspect":{"id":56,"word":"Aspect","uzbek":"jihat, tomon","type":"word","explanation":"One part or feature of a situation, idea, or problem.","izoh":"Vaziyat, g‘oya yoki muammoning bir qismi yoki xususiyati.","example":"Cost is an important aspect of choosing a university.","translation":"Universitet tanlashda xarajat muhim jihat hisoblanadi.","collocations":"important aspect / different aspects / consider every aspect"},"assess":{"id":57,"word":"Assess","uzbek":"baholamoq, aniqlamoq","type":"word","explanation":"To judge the quality, importance, or nature of something.","izoh":"Biror narsaning sifati, ahamiyati yoki xususiyatini aniqlash.","example":"The teacher will assess our speaking skills next week.","translation":"O‘qituvchi kelasi hafta gapirish ko‘nikmalarimizni baholaydi.","collocations":"assess performance / assess the risk / assess a situation"},"assessment":{"id":58,"word":"Assessment","uzbek":"baholash, baholash natijasi","type":"word","explanation":"The process of judging someone's ability, performance, or the value of something.","izoh":"Kimningdir qobiliyati, faoliyati yoki biror narsaning qiymatini aniqlash jarayoni.","example":"The final assessment includes a written test and an interview.","translation":"Yakuniy baholash yozma test va suhbatni o‘z ichiga oladi.","collocations":"final assessment / risk assessment / assessment criteria"},"assist":{"id":59,"word":"Assist","uzbek":"yordam bermoq, ko‘maklashmoq","type":"word","explanation":"To help someone do something.","izoh":"Kimningdir biror ishni bajarishiga yordam berish.","example":"A staff member will assist you with the registration process.","translation":"Xodim ro‘yxatdan o‘tish jarayonida sizga yordam beradi.","collocations":"assist a customer / assist with a task / assist someone in doing something"},"assistance":{"id":60,"word":"Assistance","uzbek":"yordam, ko‘mak","type":"word","explanation":"Help or support given to someone.","izoh":"Biror kishiga ko‘rsatiladigan yordam yoki ko‘mak.","example":"Thank you for your assistance during the move.","translation":"Ko‘chish paytida yordam berganingiz uchun rahmat.","collocations":"financial assistance / technical assistance / need assistance"},"associate":{"id":61,"word":"Associate","uzbek":"bog‘lamoq, aloqador deb bilmoq; hamkor","type":"word","explanation":"To connect someone or something with another person, idea, or event.","izoh":"Kimnidir yoki nimanidir boshqa shaxs, g‘oya yoki hodisa bilan bog‘lash.","example":"Many people associate this smell with their childhood.","translation":"Ko‘pchilik bu hidni bolaligi bilan bog‘laydi.","collocations":"associate with success / closely associated / business associate"},"association":{"id":62,"word":"Association","uzbek":"uyushma, birlashma, aloqa","type":"word","explanation":"An organized group of people, or a connection between things.","izoh":"Odamlarning tashkil etilgan guruhi yoki narsalar o‘rtasidagi bog‘liqlik.","example":"She joined a local teachers' association.","translation":"U mahalliy o‘qituvchilar uyushmasiga qo‘shildi.","collocations":"professional association / strong association / in association with"},"assume":{"id":63,"word":"Assume","uzbek":"taxmin qilmoq, deb hisoblamoq","type":"word","explanation":"To believe something is true without having proof.","izoh":"Isbotga ega bo‘lmasdan biror narsani haqiqat deb hisoblash.","example":"I assumed the shop was open because the lights were on.","translation":"Chiroqlar yonib turgani uchun do‘kon ochiq deb o‘yladim.","collocations":"assume responsibility / wrongly assume / assume that"},"assumption":{"id":64,"word":"Assumption","uzbek":"taxmin, faraz","type":"word","explanation":"Something that you believe is true without proof.","izoh":"Isbotsiz haqiqat deb qabul qilinadigan fikr yoki qarash.","example":"We should not make assumptions about other people's lives.","translation":"Boshqa odamlarning hayoti haqida taxminlar qilmasligimiz kerak.","collocations":"make an assumption / false assumption / basic assumption"},"attempt":{"id":65,"word":"Attempt","uzbek":"urinish, harakat qilmoq","type":"word","explanation":"An effort to do something, especially something difficult.","izoh":"Ayniqsa qiyin bo‘lgan ishni bajarish uchun qilingan harakat.","example":"He made an attempt to repair the computer himself.","translation":"U kompyuterni o‘zi ta’mirlashga urinib ko‘rdi.","collocations":"make an attempt / first attempt / attempt to solve"},"attend":{"id":66,"word":"Attend","uzbek":"qatnashmoq, ishtirok etmoq","type":"word","explanation":"To go to an event, meeting, or place regularly or officially.","izoh":"Tadbir, yig‘ilish yoki muayyan joyga borib qatnashmoq.","example":"All students must attend the final lesson.","translation":"Barcha o‘quvchilar yakuniy darsda qatnashishi shart.","collocations":"attend a meeting / attend school / attend a course"},"attitude":{"id":67,"word":"Attitude","uzbek":"munosabat, qarash","type":"word","explanation":"The way someone thinks or feels about something or someone.","izoh":"Kimningdir biror narsa yoki shaxs haqidagi fikri va hissiy munosabati.","example":"A positive attitude can make learning easier.","translation":"Ijobiy munosabat o‘rganishni osonlashtirishi mumkin.","collocations":"positive attitude / attitude towards work / change your attitude"},"attract":{"id":68,"word":"Attract","uzbek":"jalb qilmoq, o‘ziga tortmoq","type":"word","explanation":"To make someone interested in something or cause them to come closer.","izoh":"Kimdadir qiziqish uyg‘otish yoki uni o‘ziga yaqinlashtirish.","example":"The new shopping centre attracts visitors from nearby towns.","translation":"Yangi savdo markazi yaqin shaharlardan tashrif buyuruvchilarni jalb qiladi.","collocations":"attract attention / attract customers / attract interest"},"attraction":{"id":69,"word":"Attraction","uzbek":"diqqatga sazovor joy, joziba","type":"word","explanation":"Something that makes people interested or want to visit a place.","izoh":"Odamlarda qiziqish uyg‘otadigan yoki biror joyga borishga undaydigan narsa.","example":"The old city is the main tourist attraction.","translation":"Eski shahar asosiy sayyohlik maskanidir.","collocations":"tourist attraction / main attraction / natural attraction"},"attractive":{"id":70,"word":"Attractive","uzbek":"jozibali, chiroyli","type":"word","explanation":"Pleasant to look at or interesting and appealing.","izoh":"Ko‘rishga yoqimli yoki qiziqarli va o‘ziga tortadigan.","example":"The apartment is attractive because it is close to the city centre.","translation":"Kvartira shahar markaziga yaqinligi sababli jozibali.","collocations":"attractive design / attractive offer / physically attractive"},"authority":{"id":71,"word":"Authority","uzbek":"hokimiyat, vakolat, mutaxassis","type":"word","explanation":"The power to give orders or make decisions, or a person with expert knowledge.","izoh":"Buyruq berish yoki qaror qabul qilish huquqi, yoxud chuqur bilimga ega mutaxassis.","example":"The local authorities closed the road because of the storm.","translation":"Mahalliy hokimiyat vakillari bo‘ron sababli yo‘lni yopishdi.","collocations":"local authority / have authority / an authority on history"},"available":{"id":72,"word":"Available","uzbek":"mavjud, bo‘sh","type":"word","explanation":"Able to be used, obtained, or reached; not busy.","izoh":"Foydalanish, olish yoki murojaat qilish mumkin bo‘lgan; band bo‘lmagan.","example":"Is this room available for the weekend?","translation":"Bu xona dam olish kunlari uchun bo‘shmi?","collocations":"readily available / available online / make yourself available"},"avoid":{"id":73,"word":"Avoid","uzbek":"chetlab o‘tmoq, qochmoq","type":"word","explanation":"To stay away from someone or something, or prevent something from happening.","izoh":"Kimdir yoki nimadandir uzoq turish yoki biror hodisaning yuz berishiga yo‘l qo‘ymaslik.","example":"Try to avoid using your phone while studying.","translation":"O‘qish paytida telefoningizdan foydalanmaslikka harakat qiling.","collocations":"avoid mistakes / avoid doing something / avoid traffic"},"aware":{"id":74,"word":"Aware","uzbek":"xabardor, ogoh","type":"word","explanation":"Knowing or understanding that something exists or is happening.","izoh":"Biror narsaning mavjudligi yoki sodir bo‘layotganini bilish va tushunish.","example":"Are you aware of the changes to the timetable?","translation":"Dars jadvalidagi o‘zgarishlardan xabardormisiz?","collocations":"fully aware / become aware / aware of the risks"},"awareness":{"id":75,"word":"Awareness","uzbek":"xabardorlik, tushuncha","type":"word","explanation":"Knowledge or understanding of a situation, issue, or fact.","izoh":"Vaziyat, muammo yoki fakt haqida bilim va tushunchaga ega bo‘lish.","example":"The campaign aims to raise awareness of environmental problems.","translation":"Kampaniya ekologik muammolar haqida xabardorlikni oshirishni maqsad qilgan.","collocations":"raise awareness / public awareness / environmental awareness"},"background":{"id":76,"word":"Background","uzbek":"kelib chiqish, tajriba, fon","type":"word","explanation":"A person's education or experience, or the part behind the main subject.","izoh":"Insonning ta’limi yoki tajribasi, yoxud asosiy obyekt ortidagi qism.","example":"Her background in science helped her understand the research.","translation":"Uning ilm-fan sohasidagi tajribasi tadqiqotni tushunishiga yordam berdi.","collocations":"educational background / family background / background information"},"balance":{"id":77,"word":"Balance","uzbek":"muvozanat, muvozanatni saqlamoq","type":"word","explanation":"A state in which different parts are equal or in the correct proportions.","izoh":"Turli qismlar teng yoki to‘g‘ri nisbatda bo‘lgan holat.","example":"It is important to maintain a balance between work and rest.","translation":"Ish va dam olish o‘rtasidagi muvozanatni saqlash muhim.","collocations":"keep your balance / work-life balance / strike a balance"},"ban":{"id":78,"word":"Ban","uzbek":"taqiq, taqiqlamoq","type":"word","explanation":"An official rule that prevents something, or to officially prohibit it.","izoh":"Biror narsani man qiladigan rasmiy qoida yoki uni rasman taqiqlash.","example":"The school introduced a ban on using phones during lessons.","translation":"Maktab dars paytida telefon ishlatishni taqiqladi.","collocations":"ban smoking / impose a ban / lift a ban"},"benefit":{"id":79,"word":"Benefit","uzbek":"foyda, naf; foyda keltirmoq","type":"word","explanation":"An advantage or helpful result that something provides.","izoh":"Biror narsa keltiradigan afzallik yoki ijobiy natija.","example":"Regular exercise has many benefits for your health.","translation":"Muntazam jismoniy mashqlar sog‘lig‘ingiz uchun ko‘plab foyda keltiradi.","collocations":"health benefits / benefit from experience / mutual benefit"},"betray":{"id":80,"word":"Betray","uzbek":"xiyonat qilmoq, sotmoq","type":"word","explanation":"To hurt someone by not being loyal or by revealing their secrets.","izoh":"Sadoqatni saqlamaslik yoki sirlarini oshkor qilish orqali kimgadir zarar yetkazish.","example":"He felt that his friend had betrayed his trust.","translation":"U do‘sti uning ishonchiga xiyonat qilganini his qildi.","collocations":"betray someone's trust / betray a secret / feel betrayed"},"beyond":{"id":81,"word":"Beyond","uzbek":"narida, tashqarisida, ...dan ortiq","type":"word","explanation":"Farther away than a place, or more than a particular limit.","izoh":"Biror joydan uzoqroqda yoki muayyan chegaradan ko‘proq bo‘lgan.","example":"The village is beyond the river.","translation":"Qishloq daryoning narigi tomonida joylashgan.","collocations":"beyond expectations / beyond control / beyond repair"},"blame":{"id":82,"word":"Blame","uzbek":"ayblamoq, ayb","type":"word","explanation":"To say that someone is responsible for something bad.","izoh":"Yomon hodisa uchun kimnidir javobgar deb hisoblash yoki aytish.","example":"Don't blame yourself for a mistake that anyone could make.","translation":"Har kim qilishi mumkin bo‘lgan xato uchun o‘zingizni ayblamang.","collocations":"blame someone for / take the blame / shift the blame"},"board":{"id":83,"word":"Board","uzbek":"boshqaruv kengashi; taxta; transportga chiqmoq","type":"word","explanation":"A group that manages an organization, a flat piece of material, or to get on transport.","izoh":"Tashkilotni boshqaruvchi guruh, tekis material bo‘lagi yoki transportga chiqish harakati.","example":"Passengers should board the train ten minutes before departure.","translation":"Yo‘lovchilar poyezdga jo‘nashdan o‘n daqiqa oldin chiqishlari kerak.","collocations":"board of directors / boarding pass / notice board"},"boast":{"id":84,"word":"Boast","uzbek":"maqtanmoq","type":"word","explanation":"To talk with too much pride about your achievements or possessions.","izoh":"O‘z yutuqlari yoki mol-mulki haqida haddan tashqari faxr bilan gapirish.","example":"He never boasts about his success.","translation":"U hech qachon muvaffaqiyati bilan maqtanmaydi.","collocations":"boast about success / boast of experience / nothing to boast about"},"bold":{"id":85,"word":"Bold","uzbek":"jasur, dadil; qalin","type":"word","explanation":"Brave and confident, or easy to notice because it is strong or clear.","izoh":"Jasoratli va o‘ziga ishongan, yoxud kuchli va yaqqol ko‘rinadigan.","example":"It was a bold decision to start a business during a difficult period.","translation":"Qiyin davrda biznes boshlash dadil qaror edi.","collocations":"bold decision / bold colours / bold move"},"boost":{"id":86,"word":"Boost","uzbek":"oshirmoq, kuchaytirmoq","type":"word","explanation":"To increase or improve something.","izoh":"Biror narsani ko‘paytirish yoki yaxshilash.","example":"A short break can boost your concentration.","translation":"Qisqa tanaffus diqqatni jamlash qobiliyatini oshirishi mumkin.","collocations":"boost confidence / boost sales / boost performance"},"border":{"id":87,"word":"Border","uzbek":"chegara, chegara hududi","type":"word","explanation":"The line separating two countries or areas.","izoh":"Ikki mamlakat yoki hududni ajratib turadigan chiziq.","example":"We had to show our passports at the border.","translation":"Chegarada pasportlarimizni ko‘rsatishimizga to‘g‘ri keldi.","collocations":"cross the border / border control / border area"},"borrow":{"id":88,"word":"Borrow","uzbek":"qarzga olmoq","type":"word","explanation":"To take something from someone with the intention of returning it.","izoh":"Biror narsani keyinchalik qaytarish sharti bilan vaqtincha olmoq.","example":"Can I borrow your dictionary for a few minutes?","translation":"Lug‘atingizni bir necha daqiqaga olib tursam bo‘ladimi?","collocations":"borrow money / borrow a book / borrow from a friend"},"boundary":{"id":89,"word":"Boundary","uzbek":"chegara, chegara chizig‘i","type":"word","explanation":"A real or imaginary line that marks the limit of an area or activity.","izoh":"Hudud yoki faoliyatning chegarasini belgilovchi haqiqiy yoki xayoliy chiziq.","example":"It is important to respect other people's personal boundaries.","translation":"Boshqa odamlarning shaxsiy chegaralarini hurmat qilish muhim.","collocations":"set boundaries / national boundary / clear boundary"},"branch":{"id":90,"word":"Branch","uzbek":"filial, shox","type":"word","explanation":"A local office of an organization, or a part of a tree growing from the trunk.","izoh":"Tashkilotning mahalliy bo‘limi yoki daraxt tanasidan o‘sib chiqqan qism.","example":"The bank has opened a new branch near our school.","translation":"Bank maktabimiz yaqinida yangi filial ochdi.","collocations":"local branch / bank branch / tree branch"},"brand":{"id":91,"word":"Brand","uzbek":"brend, savdo belgisi","type":"word","explanation":"A particular product or group of products made by a company.","izoh":"Kompaniya tomonidan ishlab chiqariladigan muayyan mahsulot yoki mahsulotlar guruhi.","example":"This brand is popular among young customers.","translation":"Bu brend yosh mijozlar orasida mashhur.","collocations":"brand name / brand image / well-known brand"},"bravery":{"id":92,"word":"Bravery","uzbek":"jasorat, mardlik","type":"word","explanation":"The quality of being brave when facing danger or difficulty.","izoh":"Xavf yoki qiyinchilikka duch kelganda qo‘rqmaslik fazilati.","example":"The firefighter showed great bravery during the rescue.","translation":"O‘t o‘chiruvchi qutqaruv vaqtida katta jasorat ko‘rsatdi.","collocations":"show bravery / act of bravery / remarkable bravery"},"brief":{"id":93,"word":"Brief","uzbek":"qisqa, ixcham","type":"word","explanation":"Lasting only a short time or using few words.","izoh":"Qisqa vaqt davom etadigan yoki kam so‘z bilan ifodalangan.","example":"The manager gave us a brief explanation of the new rules.","translation":"Menejer bizga yangi qoidalarni qisqacha tushuntirdi.","collocations":"brief description / brief meeting / keep it brief"},"broad":{"id":94,"word":"Broad","uzbek":"keng, keng qamrovli","type":"word","explanation":"Wide or covering a large range of subjects or ideas.","izoh":"Keng yoki ko‘plab mavzu va g‘oyalarni qamrab oladigan.","example":"The course provides a broad introduction to computer science.","translation":"Kurs kompyuter fanlariga keng qamrovli kirish beradi.","collocations":"broad range / broad knowledge / broad agreement"},"budget":{"id":95,"word":"Budget","uzbek":"byudjet, mablag‘ rejasi","type":"word","explanation":"An amount of money available for a particular purpose or period.","izoh":"Muayyan maqsad yoki davr uchun ajratilgan pul miqdori.","example":"We need to plan our holiday within a limited budget.","translation":"Ta’tilimizni cheklangan byudjet doirasida rejalashtirishimiz kerak.","collocations":"tight budget / monthly budget / stay within budget"},"burden":{"id":96,"word":"Burden","uzbek":"yuk, og‘ir mas’uliyat","type":"word","explanation":"A difficult responsibility or something that causes worry or trouble.","izoh":"Tashvish yoki qiyinchilik keltirib chiqaradigan og‘ir mas’uliyat yoki vazifa.","example":"She did not want to become a burden on her family.","translation":"U oilasiga og‘irlik bo‘lishni istamadi.","collocations":"heavy burden / financial burden / carry a burden"},"calculate":{"id":97,"word":"Calculate","uzbek":"hisoblamoq","type":"word","explanation":"To use mathematics to find an answer or amount.","izoh":"Javob yoki miqdorni topish uchun matematik amallarni bajarish.","example":"You can calculate the total cost using this app.","translation":"Ushbu ilova yordamida umumiy xarajatni hisoblashingiz mumkin.","collocations":"calculate the cost / calculate accurately / calculate the average"},"campaign":{"id":98,"word":"Campaign","uzbek":"kampaniya, targ‘ibot tadbiri","type":"word","explanation":"A planned series of activities to achieve a particular result.","izoh":"Muayyan natijaga erishish uchun rejalashtirilgan tadbirlar ketma-ketligi.","example":"The school started a campaign to keep the neighbourhood clean.","translation":"Maktab mahallani toza saqlash bo‘yicha kampaniya boshladi.","collocations":"advertising campaign / election campaign / launch a campaign"},"cancel":{"id":99,"word":"Cancel","uzbek":"bekor qilmoq","type":"word","explanation":"To decide that an event or arrangement will not happen.","izoh":"Tadbir yoki kelishuv amalga oshmasligiga qaror qilmoq.","example":"The airline cancelled our flight because of heavy snow.","translation":"Aviakompaniya kuchli qor sababli parvozimizni bekor qildi.","collocations":"cancel a booking / cancel a meeting / cancel an order"},"candidate":{"id":100,"word":"Candidate","uzbek":"nomzod","type":"word","explanation":"A person who is being considered for a job, position, or election.","izoh":"Ish, lavozim yoki saylov uchun ko‘rib chiqilayotgan shaxs.","example":"There were twenty candidates for the teaching position.","translation":"O‘qituvchilik lavozimi uchun yigirma nafar nomzod bor edi.","collocations":"job candidate / suitable candidate / candidate for election"},"capacity":{"id":101,"word":"Capacity","uzbek":"sig‘im, qobiliyat, imkoniyat","type":"word","explanation":"The maximum amount something can contain or a person's ability to do something.","izoh":"Biror narsa sig‘dira oladigan eng katta miqdor yoki insonning biror ishni bajarish qobiliyati.","example":"The hall has a capacity of five hundred people.","translation":"Zal besh yuz kishini sig‘dira oladi.","collocations":"maximum capacity / learning capacity / production capacity"},"capital":{"id":102,"word":"Capital","uzbek":"poytaxt; kapital, sarmoya","type":"word","explanation":"The most important city of a country, or money used to start a business.","izoh":"Mamlakatning eng muhim shahri yoki biznes boshlash uchun ishlatiladigan mablag‘.","example":"Tashkent is the capital of Uzbekistan.","translation":"Toshkent — O‘zbekistonning poytaxti.","collocations":"capital city / invest capital / capital investment"},"career":{"id":103,"word":"Career","uzbek":"kasb, kasbiy faoliyat","type":"word","explanation":"The job or series of jobs that someone does during their working life.","izoh":"Insonning mehnat faoliyati davomida bajaradigan ishi yoki kasblari.","example":"She wants to build a career in international business.","translation":"U xalqaro biznes sohasida kasbiy faoliyat qurmoqchi.","collocations":"career development / career path / career opportunities"},"category":{"id":104,"word":"Category","uzbek":"toifa, turkum","type":"word","explanation":"A group of people or things that share similar features.","izoh":"O‘xshash xususiyatlarga ega odamlar yoki narsalar guruhi.","example":"Books are organised into different categories in the library.","translation":"Kutubxonada kitoblar turli toifalarga ajratilgan.","collocations":"age category / product category / fall into a category"},"cease":{"id":105,"word":"Cease","uzbek":"to‘xtatmoq, barham bermoq","type":"word","explanation":"To stop doing something or to come to an end.","izoh":"Biror ishni bajarishni to‘xtatish yoki uning yakunlanishi.","example":"The company decided to cease production of the old model.","translation":"Kompaniya eski model ishlab chiqarishni to‘xtatishga qaror qildi.","collocations":"cease operations / cease to exist / cease immediately"},"challenge":{"id":106,"word":"Challenge","uzbek":"qiyinchilik, sinov; da’vat qilmoq","type":"word","explanation":"A difficult task that tests someone's ability, or an invitation to compete.","izoh":"Insonning qobiliyatini sinaydigan qiyin vazifa yoki musobaqaga chaqiriq.","example":"Learning to drive was a challenge for me.","translation":"Mashina haydashni o‘rganish men uchun qiyin sinov bo‘ldi.","collocations":"face a challenge / meet a challenge / challenging task"},"characteristic":{"id":107,"word":"Characteristic","uzbek":"xususiyat, o‘ziga xos belgi","type":"word","explanation":"A typical quality or feature of a person or thing.","izoh":"Shaxs yoki narsaga xos bo‘lgan odatiy sifat yoki belgi.","example":"Patience is an important characteristic of a good teacher.","translation":"Sabr-toqat yaxshi o‘qituvchining muhim xususiyatidir.","collocations":"main characteristic / personal characteristic / characteristic feature"},"circumstance":{"id":108,"word":"Circumstance","uzbek":"vaziyat, sharoit","type":"word","explanation":"A fact or condition that affects what happens.","izoh":"Sodir bo‘ladigan voqeaga ta’sir ko‘rsatadigan holat yoki shart-sharoit.","example":"Under these circumstances, staying at home is safer.","translation":"Bunday sharoitda uyda qolish xavfsizroq.","collocations":"under the circumstances / difficult circumstances / personal circumstances"},"claim":{"id":109,"word":"Claim","uzbek":"da’vo, talab; da’vo qilmoq","type":"word","explanation":"To say that something is true, or a statement that something is true.","izoh":"Biror narsani haqiqat deb aytish yoki uning rostligi haqidagi bayonot.","example":"The company claims that its new phone has a longer battery life.","translation":"Kompaniya yangi telefoni batareyasi uzoqroq ishlashini da’vo qilmoqda.","collocations":"make a claim / claim responsibility / insurance claim"},"clarify":{"id":110,"word":"Clarify","uzbek":"aniqlashtirmoq, tushuntirmoq","type":"word","explanation":"To make something easier to understand by explaining it more clearly.","izoh":"Biror narsani aniqroq tushuntirish orqali tushunishni osonlashtirish.","example":"Could you clarify what you mean by this sentence?","translation":"Bu gap bilan nimani nazarda tutganingizni aniqlashtirib bera olasizmi?","collocations":"clarify a point / clarify the situation / further clarify"},"classify":{"id":111,"word":"Classify","uzbek":"tasniflamoq, guruhlarga ajratmoq","type":"word","explanation":"To arrange people or things into groups according to shared features.","izoh":"Odamlar yoki narsalarni umumiy xususiyatlariga qarab guruhlarga ajratish.","example":"Scientists classify animals according to their characteristics.","translation":"Olimlar hayvonlarni xususiyatlariga qarab tasniflaydilar.","collocations":"classify information / classify into groups / correctly classify"},"climate":{"id":112,"word":"Climate","uzbek":"iqlim","type":"word","explanation":"The usual weather conditions of a particular area over a long period.","izoh":"Muayyan hududda uzoq vaqt davomida kuzatiladigan odatiy ob-havo sharoiti.","example":"The climate in this region is hot and dry.","translation":"Bu hududning iqlimi issiq va quruq.","collocations":"climate change / tropical climate / climate conditions"},"collapse":{"id":113,"word":"Collapse","uzbek":"qulamoq, qulash","type":"word","explanation":"To fall down suddenly or fail completely.","izoh":"To‘satdan qulab tushish yoki butunlay barbod bo‘lish.","example":"The old building collapsed after the earthquake.","translation":"Eski bino zilziladan keyin qulab tushdi.","collocations":"building collapse / collapse under pressure / economic collapse"},"colleague":{"id":114,"word":"Colleague","uzbek":"hamkasb","type":"word","explanation":"A person you work with, especially in a professional job.","izoh":"Ayniqsa kasbiy faoliyatda birga ishlaydigan kishi.","example":"I discussed the lesson plan with my colleague.","translation":"Dars rejasini hamkasbim bilan muhokama qildim.","collocations":"work colleague / close colleague / former colleague"},"combine":{"id":115,"word":"Combine","uzbek":"birlashtirmoq, qo‘shmoq","type":"word","explanation":"To join two or more things together.","izoh":"Ikki yoki undan ortiq narsani bir-biriga qo‘shish.","example":"We can combine study and exercise by listening to lessons while walking.","translation":"Yurish paytida darslarni tinglash orqali o‘qish va mashqni birlashtirishimiz mumkin.","collocations":"combine ideas / combine work with study / combine ingredients"},"comfort":{"id":116,"word":"Comfort","uzbek":"qulaylik, tasalli; yupatmoq","type":"word","explanation":"A pleasant feeling of being relaxed, or something that makes someone feel better.","izoh":"O‘zini xotirjam va qulay his qilish holati yoki kishiga taskin beradigan narsa.","example":"These shoes provide comfort during long walks.","translation":"Bu oyoq kiyimlar uzoq yurishlarda qulaylik yaratadi.","collocations":"take comfort in / modern comforts / comfort someone"},"comment":{"id":117,"word":"Comment","uzbek":"izoh, sharh; fikr bildirmoq","type":"word","explanation":"Something that you say or write to express an opinion.","izoh":"Fikr yoki munosabatni bildirish uchun aytilgan yoki yozilgan gap.","example":"The teacher made a helpful comment on my essay.","translation":"O‘qituvchi inshomga foydali izoh berdi.","collocations":"make a comment / comment on a post / positive comment"},"commit":{"id":118,"word":"Commit","uzbek":"va’da bermoq, o‘zini bag‘ishlamoq; sodir etmoq","type":"word","explanation":"To promise to do something or give your time and effort to it.","izoh":"Biror ishni bajarishga va’da berish yoki unga vaqt va kuch sarflashga qaror qilish.","example":"If you commit to a daily routine, your English will improve.","translation":"Agar kundalik tartibga qat’iy rioya qilsangiz, ingliz tilingiz yaxshilanadi.","collocations":"commit to a plan / commit time / commit a crime"},"commitment":{"id":119,"word":"Commitment","uzbek":"sadoqat, majburiyat, qat’iylik","type":"word","explanation":"A promise or willingness to give time and effort to something.","izoh":"Biror narsaga vaqt va kuch sarflashga tayyorlik yoki berilgan va’da.","example":"Learning a language requires commitment and patience.","translation":"Til o‘rganish qat’iyat va sabr-toqatni talab qiladi.","collocations":"strong commitment / make a commitment / long-term commitment"},"communication":{"id":120,"word":"Communication","uzbek":"muloqot, aloqa","type":"word","explanation":"The process of sharing information, ideas, or feelings with others.","izoh":"Boshqalar bilan ma’lumot, fikr yoki his-tuyg‘ularni almashish jarayoni.","example":"Good communication helps teams solve problems faster.","translation":"Yaxshi muloqot jamoalarga muammolarni tezroq hal qilishga yordam beradi.","collocations":"effective communication / communication skills / face-to-face communication"},"community":{"id":121,"word":"Community","uzbek":"jamoa, hamjamiyat, mahalla","type":"word","explanation":"A group of people living in the same area or sharing an interest.","izoh":"Bir hududda yashaydigan yoki umumiy qiziqishga ega bo‘lgan odamlar guruhi.","example":"The local community organised a clean-up event.","translation":"Mahalliy hamjamiyat hududni tozalash tadbirini tashkil qildi.","collocations":"local community / online community / community service"},"compare":{"id":122,"word":"Compare","uzbek":"taqqoslamoq, solishtirmoq","type":"word","explanation":"To examine two or more things to find similarities and differences.","izoh":"O‘xshashlik va farqlarni aniqlash uchun ikki yoki undan ortiq narsani tekshirish.","example":"Compare the prices before you buy a new phone.","translation":"Yangi telefon sotib olishdan oldin narxlarni solishtiring.","collocations":"compare prices / compare results / compare with the original"},"comparison":{"id":123,"word":"Comparison","uzbek":"taqqoslash, solishtirish","type":"word","explanation":"The act of examining similarities and differences between things.","izoh":"Narsalar o‘rtasidagi o‘xshashlik va farqlarni o‘rganish jarayoni.","example":"A comparison of the two courses helped me choose one.","translation":"Ikki kursni taqqoslash menga birini tanlashga yordam berdi.","collocations":"make a comparison / direct comparison / in comparison with"},"compete":{"id":124,"word":"Compete","uzbek":"raqobatlashmoq, bellashmoq","type":"word","explanation":"To try to be more successful than others in a contest or activity.","izoh":"Musobaqa yoki faoliyatda boshqalardan muvaffaqiyatliroq bo‘lishga harakat qilish.","example":"Small businesses must compete with larger companies.","translation":"Kichik bizneslar yirik kompaniyalar bilan raqobatlashishi kerak.","collocations":"compete for a job / compete against others / compete internationally"},"competition":{"id":125,"word":"Competition","uzbek":"raqobat, musobaqa","type":"word","explanation":"An activity in which people or organizations try to be more successful than others.","izoh":"Odamlar yoki tashkilotlar boshqalardan ustun bo‘lishga intiladigan faoliyat.","example":"Competition between online shops has reduced prices.","translation":"Onlayn do‘konlar o‘rtasidagi raqobat narxlarni pasaytirdi.","collocations":"strong competition / face competition / enter a competition"},"competitive":{"id":126,"word":"Competitive","uzbek":"raqobatbardosh, raqobatli","type":"word","explanation":"Able or likely to compete successfully, or involving competition.","izoh":"Muvaffaqiyatli raqobatlasha oladigan yoki raqobat mavjud bo‘lgan.","example":"The company offers competitive prices.","translation":"Kompaniya raqobatbardosh narxlarni taklif qiladi.","collocations":"competitive market / competitive salary / highly competitive"},"competitor":{"id":127,"word":"Competitor","uzbek":"raqib, raqobatchi","type":"word","explanation":"A person or organization that competes with another.","izoh":"Boshqa shaxs yoki tashkilot bilan raqobatlashadigan kishi yoki tashkilot.","example":"Our main competitor has launched a similar product.","translation":"Asosiy raqibimiz shunga o‘xshash mahsulotni bozorga chiqardi.","collocations":"main competitor / business competitor / direct competitor"},"complain":{"id":128,"word":"Complain","uzbek":"shikoyat qilmoq, nolimoq","type":"word","explanation":"To say that something is wrong or that you are unhappy about it.","izoh":"Biror narsadan norozi ekanini yoki unda muammo borligini aytish.","example":"Several customers complained about the slow service.","translation":"Bir nechta mijoz xizmatning sekinligidan shikoyat qildi.","collocations":"complain about noise / complain to a manager / formally complain"},"complaint":{"id":129,"word":"Complaint","uzbek":"shikoyat, norozilik","type":"word","explanation":"A statement that something is wrong or unsatisfactory.","izoh":"Biror narsaning noto‘g‘ri yoki qoniqarsiz ekanini bildiruvchi bayonot.","example":"The hotel received a complaint about the heating system.","translation":"Mehmonxona isitish tizimi haqida shikoyat oldi.","collocations":"make a complaint / handle a complaint / formal complaint"},"complex":{"id":130,"word":"Complex","uzbek":"murakkab, majmua","type":"word","explanation":"Difficult to understand or made of many connected parts; a group of buildings.","izoh":"Tushunish qiyin yoki ko‘plab o‘zaro bog‘langan qismlardan tashkil topgan; binolar majmuasi.","example":"The problem is more complex than it first appears.","translation":"Muammo dastlab ko‘ringanidan murakkabroq.","collocations":"complex problem / complex system / sports complex"},"complexity":{"id":131,"word":"Complexity","uzbek":"murakkablik","type":"word","explanation":"The state of having many connected parts or being difficult to understand.","izoh":"Ko‘plab o‘zaro bog‘langan qismlarga ega bo‘lish yoki tushunish qiyinligi.","example":"The complexity of the task surprised the new employees.","translation":"Vazifaning murakkabligi yangi xodimlarni hayratda qoldirdi.","collocations":"deal with complexity / increasing complexity / level of complexity"},"component":{"id":132,"word":"Component","uzbek":"tarkibiy qism, komponent","type":"word","explanation":"One of the parts that make up a larger system or object.","izoh":"Kattaroq tizim yoki buyumni tashkil etuvchi qismlardan biri.","example":"The battery is an important component of a laptop.","translation":"Batareya noutbukning muhim tarkibiy qismidir.","collocations":"key component / electronic component / main component"},"concentrate":{"id":133,"word":"Concentrate","uzbek":"diqqatni jamlamoq, to‘planmoq","type":"word","explanation":"To give all your attention to something.","izoh":"Butun e’tiborni biror narsaga qaratish.","example":"I find it difficult to concentrate when the room is noisy.","translation":"Xona shovqinli bo‘lganda diqqatimni jamlashim qiyin.","collocations":"concentrate on work / concentrate fully / ability to concentrate"},"concentration":{"id":134,"word":"Concentration","uzbek":"diqqatni jamlash, diqqat","type":"word","explanation":"The ability to give your attention to one thing for a period of time.","izoh":"Ma’lum vaqt davomida e’tiborni bitta narsaga qaratish qobiliyati.","example":"Regular breaks can improve your concentration.","translation":"Muntazam tanaffuslar diqqatni jamlash qobiliyatini yaxshilashi mumkin.","collocations":"deep concentration / lose concentration / improve concentration"},"concept":{"id":135,"word":"Concept","uzbek":"tushuncha, g‘oya","type":"word","explanation":"An idea or principle that helps people understand something.","izoh":"Biror narsani tushunishga yordam beradigan g‘oya yoki tamoyil.","example":"The concept of online learning became popular during the pandemic.","translation":"Pandemiya davrida onlayn ta’lim tushunchasi ommalashdi.","collocations":"basic concept / key concept / understand a concept"},"concern":{"id":136,"word":"Concern","uzbek":"tashvish, muammo; tashvishlanmoq","type":"word","explanation":"A feeling of worry, or something that is important to someone.","izoh":"Xavotir hissi yoki kimdir uchun muhim bo‘lgan masala.","example":"Safety is our main concern during the trip.","translation":"Sayohat davomida xavfsizlik bizning asosiy tashvishimizdir.","collocations":"major concern / express concern / concern about safety"},"concerned":{"id":137,"word":"Concerned","uzbek":"xavotirlangan, aloqador","type":"word","explanation":"Worried about something, or involved in a particular matter.","izoh":"Biror narsa haqida tashvishlangan yoki muayyan masalaga aloqador.","example":"Parents are concerned about the amount of time children spend online.","translation":"Ota-onalar bolalarning internetda o‘tkazadigan vaqtidan xavotirda.","collocations":"deeply concerned / concerned about health / all concerned"},"conduct":{"id":138,"word":"Conduct","uzbek":"o‘tkazmoq, olib bormoq; xulq-atvor","type":"word","explanation":"To organize or carry out an activity, or the way someone behaves.","izoh":"Biror faoliyatni tashkil etish yoki amalga oshirish; insonning o‘zini tutishi.","example":"The university will conduct a survey among students.","translation":"Universitet talabalar o‘rtasida so‘rovnoma o‘tkazadi.","collocations":"conduct research / conduct an interview / professional conduct"},"confidence":{"id":139,"word":"Confidence","uzbek":"ishonch, o‘ziga ishonch","type":"word","explanation":"A feeling of trust in yourself or someone else.","izoh":"O‘ziga yoki boshqa kishiga bo‘lgan ishonch hissi.","example":"Speaking English every day has improved my confidence.","translation":"Har kuni ingliz tilida gapirish o‘zimga bo‘lgan ishonchimni oshirdi.","collocations":"self-confidence / build confidence / have confidence in"},"confident":{"id":140,"word":"Confident","uzbek":"o‘ziga ishongan, ishonchli","type":"word","explanation":"Feeling sure about your abilities or that something is true.","izoh":"O‘z qobiliyatiga yoki biror narsaning to‘g‘riligiga ishonadigan.","example":"She felt confident during the job interview.","translation":"U ish suhbatida o‘zini ishonchli his qildi.","collocations":"feel confident / confident speaker / confident decision"},"confirm":{"id":141,"word":"Confirm","uzbek":"tasdiqlamoq, aniqlashtirmoq","type":"word","explanation":"To say or show that something is true or definite.","izoh":"Biror narsaning rost yoki aniq ekanini aytish yoxud ko‘rsatish.","example":"Please confirm your appointment by email.","translation":"Iltimos, uchrashuvni elektron pochta orqali tasdiqlang.","collocations":"confirm a booking / confirm details / officially confirm"},"conflict":{"id":142,"word":"Conflict","uzbek":"nizo, ziddiyat, to‘qnashuv","type":"word","explanation":"A serious disagreement or a situation in which ideas or interests oppose each other.","izoh":"Jiddiy kelishmovchilik yoki fikr va manfaatlar qarama-qarshi keladigan vaziyat.","example":"The two departments had a conflict over the budget.","translation":"Ikki bo‘lim o‘rtasida byudjet masalasida nizo yuzaga keldi.","collocations":"avoid conflict / conflict of interest / armed conflict"},"confuse":{"id":143,"word":"Confuse","uzbek":"adashtirmoq, chalkashtirmoq","type":"word","explanation":"To make someone unable to understand something clearly.","izoh":"Kimningdir biror narsani aniq tushunishiga xalaqit berish.","example":"The similar names confused the new students.","translation":"O‘xshash ismlar yangi o‘quvchilarni adashtirdi.","collocations":"confuse someone / easily confused / confuse A with B"},"confused":{"id":144,"word":"Confused","uzbek":"hayron, boshi qotgan, chalkashgan","type":"word","explanation":"Unable to understand something or decide what to do.","izoh":"Biror narsani tushunolmayotgan yoki nima qilishni bilmayotgan holat.","example":"I was confused by the instructions on the form.","translation":"Shakldagi ko‘rsatmalar meni chalkashtirib yubordi.","collocations":"feel confused / completely confused / confused about something"},"confusion":{"id":145,"word":"Confusion","uzbek":"chalkashlik, tushunmovchilik","type":"word","explanation":"A state of not understanding something clearly or being uncertain.","izoh":"Biror narsani aniq tushunmaslik yoki noaniqlik holati.","example":"There was some confusion about the meeting time.","translation":"Yig‘ilish vaqti borasida biroz tushunmovchilik bo‘ldi.","collocations":"cause confusion / avoid confusion / in a state of confusion"},"conscious":{"id":146,"word":"Conscious","uzbek":"ongli, hushyor","type":"word","explanation":"Awake and aware of what is happening around you; deliberate.","izoh":"Uyg‘oq va atrofida sodir bo‘layotgan voqealardan xabardor; ataylab qilingan.","example":"He was still conscious when the ambulance arrived.","translation":"Tez yordam kelganida u hali hushida edi.","collocations":"conscious decision / remain conscious / environmentally conscious"},"consequence":{"id":147,"word":"Consequence","uzbek":"oqibat, natija","type":"word","explanation":"A result of an action or situation, especially an unpleasant one.","izoh":"Biror harakat yoki vaziyatning natijasi, ayniqsa yoqimsiz oqibat.","example":"Every decision has consequences.","translation":"Har bir qarorning o‘z oqibatlari bor.","collocations":"serious consequences / face the consequences / as a consequence"},"conservative":{"id":148,"word":"Conservative","uzbek":"konservativ, an’anaparast, ehtiyotkor","type":"word","explanation":"Preferring traditional values or avoiding unnecessary change or risk.","izoh":"An’anaviy qadriyatlarni afzal ko‘radigan yoki keraksiz o‘zgarish va xavfdan qochadigan.","example":"The company takes a conservative approach to spending.","translation":"Kompaniya xarajatlar masalasida ehtiyotkor yondashuvni qo‘llaydi.","collocations":"conservative approach / conservative estimate / traditional conservative values"},"consider":{"id":149,"word":"Consider","uzbek":"ko‘rib chiqmoq, o‘ylab ko‘rmoq","type":"word","explanation":"To think carefully about something before making a decision.","izoh":"Qaror qabul qilishdan oldin biror narsa haqida yaxshilab o‘ylash.","example":"We are considering moving to a larger apartment.","translation":"Biz kattaroq kvartiraga ko‘chishni o‘ylab ko‘ryapmiz.","collocations":"consider an option / carefully consider / consider doing something"},"considerable":{"id":150,"word":"Considerable","uzbek":"sezilarli, anchagina","type":"word","explanation":"Large in size, amount, or importance.","izoh":"Hajmi, miqdori yoki ahamiyati jihatidan katta bo‘lgan.","example":"The project requires a considerable amount of time.","translation":"Loyiha anchagina vaqt talab qiladi.","collocations":"considerable effort / considerable amount / considerable improvement"},"consideration":{"id":151,"word":"Consideration","uzbek":"e’tibor, mulohaza, hisobga olish","type":"word","explanation":"Careful thought about something, or attention given to someone.","izoh":"Biror narsa haqida puxta o‘ylash yoki kimgadir e’tibor ko‘rsatish.","example":"You should take all the costs into consideration.","translation":"Barcha xarajatlarni hisobga olishingiz kerak.","collocations":"take into consideration / careful consideration / show consideration"},"consist":{"id":152,"word":"Consist","uzbek":"iborat bo‘lmoq, tashkil topmoq","type":"word","explanation":"To be made up of particular parts or members.","izoh":"Muayyan qismlar yoki a’zolardan tashkil topmoq.","example":"The course consists of twelve weekly lessons.","translation":"Kurs haftasiga bir martadan o‘tkaziladigan o‘n ikki darsdan iborat.","collocations":"consist of / mainly consist of / consist entirely of"},"consistent":{"id":153,"word":"Consistent","uzbek":"izchil, barqaror, bir xil","type":"word","explanation":"Always behaving or happening in the same way; not changing unexpectedly.","izoh":"Doimo bir xil tarzda sodir bo‘ladigan yoki kutilmaganda o‘zgarmaydigan.","example":"Consistent practice is the key to improving pronunciation.","translation":"Izchil mashq qilish talaffuzni yaxshilashning kalitidir.","collocations":"consistent effort / remain consistent / consistent results"},"constant":{"id":154,"word":"Constant","uzbek":"doimiy, uzluksiz","type":"word","explanation":"Happening all the time or staying the same.","izoh":"Har doim sodir bo‘ladigan yoki o‘zgarmasdan qoladigan.","example":"Constant notifications make it difficult to focus.","translation":"Tinimsiz bildirishnomalar diqqatni jamlashni qiyinlashtiradi.","collocations":"constant pressure / constant change / constant communication"},"constantly":{"id":155,"word":"Constantly","uzbek":"doim, tinimsiz","type":"word","explanation":"All the time or very frequently.","izoh":"Har doim yoki juda tez-tez.","example":"My phone is constantly receiving messages.","translation":"Telefonimga tinimsiz xabarlar keladi.","collocations":"constantly changing / constantly improve / constantly remind"},"construct":{"id":156,"word":"Construct","uzbek":"qurmoq, bunyod etmoq","type":"word","explanation":"To build something large, or form an idea or sentence.","izoh":"Katta inshoot qurish yoki fikr yoxud gapni shakllantirish.","example":"The city plans to construct a new bridge.","translation":"Shahar yangi ko‘prik qurishni rejalashtirmoqda.","collocations":"construct a building / construct an argument / construct a sentence"},"construction":{"id":157,"word":"Construction","uzbek":"qurilish, qurish jarayoni","type":"word","explanation":"The process of building something such as a house, road, or bridge.","izoh":"Uy, yo‘l yoki ko‘prik kabi inshootlarni qurish jarayoni.","example":"Road construction has caused delays this week.","translation":"Bu hafta yo‘l qurilishi sababli kechikishlar yuz berdi.","collocations":"under construction / construction work / construction industry"},"consume":{"id":158,"word":"Consume","uzbek":"iste’mol qilmoq, sarflamoq","type":"word","explanation":"To eat, drink, or use something, or use up a resource.","izoh":"Biror narsani yeyish, ichish yoki ishlatish, yoxud resursni sarflash.","example":"People should consume less sugar.","translation":"Odamlar kamroq shakar iste’mol qilishlari kerak.","collocations":"consume energy / consume food / consume large amounts"},"consumer":{"id":159,"word":"Consumer","uzbek":"iste’molchi, xaridor","type":"word","explanation":"A person who buys or uses goods and services.","izoh":"Tovar va xizmatlarni sotib oladigan yoki ulardan foydalanadigan shaxs.","example":"Consumers are paying more attention to product quality.","translation":"Iste’molchilar mahsulot sifatiga ko‘proq e’tibor qaratishmoqda.","collocations":"consumer rights / consumer behaviour / consumer demand"},"consumption":{"id":160,"word":"Consumption","uzbek":"iste’mol, sarf","type":"word","explanation":"The act of using food, energy, or other resources.","izoh":"Oziq-ovqat, energiya yoki boshqa resurslardan foydalanish jarayoni.","example":"The report examines household water consumption.","translation":"Hisobot uy xo‘jaliklarida suv iste’molini o‘rganadi.","collocations":"energy consumption / food consumption / reduce consumption"},"contact":{"id":161,"word":"Contact","uzbek":"aloqa, bog‘lanish; bog‘lanmoq","type":"word","explanation":"Communication with someone, or the act of communicating with them.","izoh":"Kimdir bilan muloqot qilish yoki aloqa o‘rnatish.","example":"Please contact the office if you have any questions.","translation":"Savollaringiz bo‘lsa, iltimos, idora bilan bog‘laning.","collocations":"keep in contact / contact details / make contact with"},"contemporary":{"id":162,"word":"Contemporary","uzbek":"zamonaviy, hozirgi davrga oid","type":"word","explanation":"Belonging to the present time or the same period in history.","izoh":"Hozirgi davrga yoki tarixdagi bir davrga tegishli bo‘lgan.","example":"The museum displays contemporary art.","translation":"Muzeyda zamonaviy san’at namoyish etiladi.","collocations":"contemporary art / contemporary society / contemporary issues"},"content":{"id":163,"word":"Content","uzbek":"mazmun, tarkib; mamnun","type":"word","explanation":"The information or ideas contained in something; satisfied.","izoh":"Biror narsa ichidagi ma’lumot yoki g‘oyalar; mamnun holat.","example":"The website contains useful educational content.","translation":"Veb-saytda foydali ta’limiy mazmun mavjud.","collocations":"online content / table of contents / content creator"},"contrast":{"id":164,"word":"Contrast","uzbek":"qarama-qarshilik, farq; taqqoslamoq","type":"word","explanation":"A clear difference between two things, or to compare them to show differences.","izoh":"Ikki narsa o‘rtasidagi yaqqol farq yoki farqlarni ko‘rsatish uchun ularni solishtirish.","example":"The contrast between city life and village life is clear.","translation":"Shahar hayoti va qishloq hayoti o‘rtasidagi farq yaqqol.","collocations":"in contrast to / sharp contrast / contrast two ideas"},"contribute":{"id":165,"word":"Contribute","uzbek":"hissa qo‘shmoq, yordam bermoq","type":"word","explanation":"To give money, time, ideas, or effort to help achieve something.","izoh":"Biror maqsadga erishish uchun pul, vaqt, g‘oya yoki kuch sarflash.","example":"Everyone can contribute to keeping the environment clean.","translation":"Atrof-muhitni toza saqlashga har kim hissa qo‘sha oladi.","collocations":"contribute to society / contribute money / make a contribution"},"contribution":{"id":166,"word":"Contribution","uzbek":"hissa, qo‘shilgan ulush","type":"word","explanation":"Something that you give or do to help achieve a result.","izoh":"Natijaga erishishga yordam berish uchun berilgan narsa yoki bajarilgan ish.","example":"Her contribution made the project more successful.","translation":"Uning qo‘shgan hissasi loyihani yanada muvaffaqiyatli qildi.","collocations":"make a contribution / valuable contribution / contribution to research"},"convenient":{"id":167,"word":"Convenient","uzbek":"qulay, mos","type":"word","explanation":"Easy to use or suitable for someone's needs or plans.","izoh":"Foydalanish oson yoki kimningdir ehtiyoj va rejalariga mos bo‘lgan.","example":"Online banking is convenient for busy people.","translation":"Onlayn bank xizmatlari band odamlar uchun qulay.","collocations":"convenient location / convenient time / more convenient"},"convention":{"id":168,"word":"Convention","uzbek":"anjuman, an’ana, qabul qilingan qoida","type":"word","explanation":"A large formal meeting, or a usual and accepted way of doing something.","izoh":"Katta rasmiy yig‘ilish yoki biror ishni bajarishning odatiy va qabul qilingan usuli.","example":"The company will present its products at an international convention.","translation":"Kompaniya mahsulotlarini xalqaro anjumanda taqdim etadi.","collocations":"annual convention / social convention / follow convention"},"conventional":{"id":169,"word":"Conventional","uzbek":"an’anaviy, odatiy","type":"word","explanation":"Following the usual or accepted way of doing something.","izoh":"Biror ishni bajarishning odatiy yoki qabul qilingan usuliga amal qiladigan.","example":"They chose a conventional design for the new office.","translation":"Ular yangi ofis uchun an’anaviy dizaynni tanlashdi.","collocations":"conventional method / conventional approach / conventional medicine"},"convert":{"id":170,"word":"Convert","uzbek":"o‘zgartirmoq, aylantirmoq","type":"word","explanation":"To change something into a different form or use.","izoh":"Biror narsani boshqa shakl yoki foydalanish turiga o‘zgartirish.","example":"You can convert the document into a PDF file.","translation":"Hujjatni PDF faylga aylantirishingiz mumkin.","collocations":"convert a file / convert into energy / convert currency"},"convince":{"id":171,"word":"Convince","uzbek":"ishontirmoq","type":"word","explanation":"To make someone believe that something is true or worth doing.","izoh":"Kimnidir biror narsaning rost yoki bajarishga arziydigan ekaniga ishontirish.","example":"I tried to convince my parents to let me study abroad.","translation":"Ota-onamni chet elda o‘qishimga ruxsat berishga ishontirishga harakat qildim.","collocations":"convince someone to / convince someone that / hard to convince"},"convinced":{"id":172,"word":"Convinced","uzbek":"ishongan, amin bo‘lgan","type":"word","explanation":"Certain that something is true or that a particular action is right.","izoh":"Biror narsaning rostligiga yoki muayyan harakat to‘g‘riligiga amin bo‘lgan.","example":"I am convinced that regular practice works.","translation":"Muntazam mashq foyda berishiga aminman.","collocations":"firmly convinced / convinced that / become convinced"},"cooperate":{"id":173,"word":"Cooperate","uzbek":"hamkorlik qilmoq","type":"word","explanation":"To work together with someone to achieve a shared result.","izoh":"Umumiy natijaga erishish uchun kim bilandir birgalikda ishlash.","example":"The two schools agreed to cooperate on a language project.","translation":"Ikki maktab til loyihasida hamkorlik qilishga kelishib oldi.","collocations":"cooperate with others / closely cooperate / cooperate fully"},"cooperation":{"id":174,"word":"Cooperation","uzbek":"hamkorlik","type":"word","explanation":"The process of working together towards a common goal.","izoh":"Umumiy maqsad sari birgalikda ishlash jarayoni.","example":"International cooperation is important for protecting the environment.","translation":"Atrof-muhitni himoya qilishda xalqaro hamkorlik muhimdir.","collocations":"international cooperation / close cooperation / encourage cooperation"},"core":{"id":175,"word":"Core","uzbek":"asosiy, markaziy; o‘zak","type":"word","explanation":"The most important or central part of something.","izoh":"Biror narsaning eng muhim yoki markaziy qismi.","example":"Communication is a core skill in almost every profession.","translation":"Muloqot deyarli har bir kasbdagi asosiy ko‘nikmadir.","collocations":"core values / core skills / at the core of"},"corporate":{"id":176,"word":"Corporate","uzbek":"korporativ, kompaniyaga oid","type":"word","explanation":"Relating to a large company or business organization.","izoh":"Yirik kompaniya yoki biznes tashkilotiga tegishli.","example":"She works in the corporate sector.","translation":"U korporativ sektorda ishlaydi.","collocations":"corporate culture / corporate office / corporate responsibility"},"corporation":{"id":177,"word":"Corporation","uzbek":"korporatsiya, yirik kompaniya","type":"word","explanation":"A large company or group of companies operating as one organization.","izoh":"Yagona tashkilot sifatida faoliyat yuritadigan yirik kompaniya yoki kompaniyalar guruhi.","example":"The corporation employs thousands of people worldwide.","translation":"Korporatsiya butun dunyo bo‘ylab minglab odamlarni ish bilan ta’minlaydi.","collocations":"large corporation / multinational corporation / corporation tax"},"correspond":{"id":178,"word":"Correspond","uzbek":"mos kelmoq, yozishmoq","type":"word","explanation":"To be similar or match something, or communicate by writing.","izoh":"Biror narsaga o‘xshash yoki mos bo‘lish, yoxud yozma ravishda muloqot qilish.","example":"The figures in the report correspond to the latest data.","translation":"Hisobotdagi raqamlar eng so‘nggi ma’lumotlarga mos keladi.","collocations":"correspond with reality / correspond to a description / correspond by email"},"correspondence":{"id":179,"word":"Correspondence","uzbek":"yozishmalar, xat-xabar","type":"word","explanation":"Letters, emails, or other written communication between people.","izoh":"Odamlar o‘rtasidagi xatlar, elektron xabarlar yoki boshqa yozma muloqot.","example":"I keep all business correspondence in a separate folder.","translation":"Barcha ish yozishmalarini alohida papkada saqlayman.","collocations":"business correspondence / email correspondence / official correspondence"},"create":{"id":180,"word":"Create","uzbek":"yaratmoq, tashkil etmoq","type":"word","explanation":"To make something new or cause something to exist.","izoh":"Yangi narsani yasash yoki biror narsaning paydo bo‘lishiga sabab bo‘lish.","example":"The students created a website for their school project.","translation":"O‘quvchilar maktab loyihasi uchun veb-sayt yaratishdi.","collocations":"create an opportunity / create a website / create a problem"},"creative":{"id":181,"word":"Creative","uzbek":"ijodiy, ijodkor","type":"word","explanation":"Having the ability to produce original ideas or things.","izoh":"O‘ziga xos g‘oyalar yoki narsalarni yaratish qobiliyatiga ega bo‘lgan.","example":"The teacher encouraged students to find creative solutions.","translation":"O‘qituvchi o‘quvchilarni ijodiy yechimlar topishga undadi.","collocations":"creative thinking / creative solution / creative process"},"creativity":{"id":182,"word":"Creativity","uzbek":"ijodkorlik, ijodiylik","type":"word","explanation":"The ability to produce new and original ideas or things.","izoh":"Yangi va o‘ziga xos g‘oyalar yoki narsalarni yaratish qobiliyati.","example":"Creativity is useful in both art and science.","translation":"Ijodkorlik san’atda ham, ilm-fanda ham foydalidir.","collocations":"encourage creativity / creative thinking / show creativity"},"credit":{"id":183,"word":"Credit","uzbek":"kredit, ishonch; xizmatni e’tirof etish","type":"word","explanation":"Money that you borrow, recognition for an achievement, or belief in someone.","izoh":"Qarzga olingan pul, yutuq uchun e’tirof yoki kimgadir bo‘lgan ishonch.","example":"She deserves credit for organising the event.","translation":"Tadbirni tashkil qilgani uchun u e’tirofga loyiq.","collocations":"give credit / credit card / take credit for"},"crime":{"id":184,"word":"Crime","uzbek":"jinoyat","type":"word","explanation":"An illegal activity that can be punished by law.","izoh":"Qonun bilan jazolanishi mumkin bo‘lgan noqonuniy faoliyat.","example":"The police are investigating the crime.","translation":"Politsiya jinoyatni tergov qilmoqda.","collocations":"commit a crime / crime rate / prevent crime"},"criminal":{"id":185,"word":"Criminal","uzbek":"jinoyatchi; jinoiy","type":"word","explanation":"A person who has committed a crime, or relating to crime.","izoh":"Jinoyat sodir etgan shaxs yoki jinoyatga aloqador narsa.","example":"The criminal was arrested near the station.","translation":"Jinoyatchi vokzal yaqinida qo‘lga olindi.","collocations":"criminal record / criminal investigation / criminal offence"},"crisis":{"id":186,"word":"Crisis","uzbek":"inqiroz, tanglik","type":"word","explanation":"A time of great difficulty, danger, or uncertainty.","izoh":"Katta qiyinchilik, xavf yoki noaniqlik davri.","example":"The hospital faced a serious staff crisis.","translation":"Kasalxona xodimlar bilan bog‘liq jiddiy tanglikka duch keldi.","collocations":"economic crisis / face a crisis / crisis management"},"criterion":{"id":187,"word":"Criterion","uzbek":"mezon","type":"word","explanation":"A standard used to judge or decide something.","izoh":"Biror narsani baholash yoki qaror qabul qilishda ishlatiladigan standart.","example":"Price is not the only criterion when choosing a laptop.","translation":"Noutbuk tanlashda narx yagona mezon emas.","collocations":"selection criterion / meet the criteria / main criterion"},"critical":{"id":188,"word":"Critical","uzbek":"tanqidiy, juda muhim","type":"word","explanation":"Expressing criticism, or extremely important to a situation.","izoh":"Tanqid bildiradigan yoki vaziyat uchun nihoyatda muhim bo‘lgan.","example":"It is critical to save your work regularly.","translation":"Ishingizni muntazam saqlab borish juda muhim.","collocations":"critical thinking / critical condition / critically important"},"criticism":{"id":189,"word":"Criticism","uzbek":"tanqid","type":"word","explanation":"The act of expressing disapproval or pointing out faults.","izoh":"Norozilik bildirish yoki kamchiliklarni ko‘rsatish harakati.","example":"The new policy received criticism from employees.","translation":"Yangi siyosat xodimlar tomonidan tanqidga uchradi.","collocations":"constructive criticism / receive criticism / public criticism"},"criticise":{"id":190,"word":"Criticise","uzbek":"tanqid qilmoq","type":"word","explanation":"To express disapproval of someone or something by pointing out faults.","izoh":"Kamchiliklarni ko‘rsatish orqali kimdir yoki nimadagi norozilikni bildirish.","example":"It is easy to criticise, but harder to offer a solution.","translation":"Tanqid qilish oson, ammo yechim taklif qilish qiyinroq.","collocations":"criticise a decision / openly criticise / criticise unfairly"},"crop":{"id":191,"word":"Crop","uzbek":"ekin, hosil; kesib olmoq","type":"word","explanation":"A plant grown for food or other use, or to cut part of an image.","izoh":"Oziq-ovqat yoki boshqa maqsadda yetishtiriladigan o‘simlik; rasmning bir qismini kesish.","example":"Farmers grow several crops in this region.","translation":"Dehqonlar bu hududda bir nechta turdagi ekin yetishtiradilar.","collocations":"crop production / harvest a crop / crop failure"},"crucial":{"id":192,"word":"Crucial","uzbek":"hal qiluvchi, nihoyatda muhim","type":"word","explanation":"Extremely important because it affects the final result.","izoh":"Yakuniy natijaga ta’sir qilgani sababli nihoyatda muhim bo‘lgan.","example":"Good preparation is crucial for success in the exam.","translation":"Yaxshi tayyorgarlik imtihonda muvaffaqiyatga erishish uchun hal qiluvchi ahamiyatga ega.","collocations":"crucial decision / crucial role / crucial factor"},"cultural":{"id":193,"word":"Cultural","uzbek":"madaniy, madaniyatga oid","type":"word","explanation":"Related to the customs, beliefs, art, and way of life of a group.","izoh":"Biror guruhning urf-odatlari, e’tiqodi, san’ati va turmush tarziga oid.","example":"The festival is an important cultural event.","translation":"Festival muhim madaniy tadbirdir.","collocations":"cultural differences / cultural heritage / cultural exchange"},"culture":{"id":194,"word":"Culture","uzbek":"madaniyat","type":"word","explanation":"The customs, beliefs, art, and way of life of a society or group.","izoh":"Jamiyat yoki guruhning urf-odatlari, e’tiqodi, san’ati va turmush tarzi.","example":"Learning a language also means learning about its culture.","translation":"Til o‘rganish uning madaniyati haqida ham bilishni anglatadi.","collocations":"local culture / popular culture / cultural diversity"},"currency":{"id":195,"word":"Currency","uzbek":"valyuta, pul birligi","type":"word","explanation":"The system of money used in a particular country.","izoh":"Muayyan mamlakatda ishlatiladigan pul tizimi yoki pul birligi.","example":"You should check the exchange rate before changing currency.","translation":"Valyutani almashtirishdan oldin ayirboshlash kursini tekshirishingiz kerak.","collocations":"foreign currency / local currency / currency exchange"},"current":{"id":196,"word":"Current","uzbek":"hozirgi, joriy; oqim","type":"word","explanation":"Happening or existing now; also, the movement of water or electricity.","izoh":"Hozir sodir bo‘layotgan yoki mavjud bo‘lgan; shuningdek, suv yoki elektr oqimi.","example":"Please provide your current address on the form.","translation":"Iltimos, shaklda hozirgi manzilingizni ko‘rsating.","collocations":"current situation / current account / current affairs"},"currently":{"id":197,"word":"Currently","uzbek":"hozirda, ayni paytda","type":"word","explanation":"At the present time.","izoh":"Hozirgi vaqtda.","example":"I am currently studying for my English exam.","translation":"Men hozirda ingliz tili imtihonimga tayyorlanyapman.","collocations":"currently available / currently working / currently under review"},"custom":{"id":198,"word":"Custom","uzbek":"urf-odat, rasm-rusum; buyurtma asosida tayyorlangan","type":"word","explanation":"A traditional way of behaving, or something made for a particular person.","izoh":"An’anaviy xulq-atvor usuli yoki muayyan shaxs uchun tayyorlangan narsa.","example":"It is a local custom to visit relatives during the holiday.","translation":"Bayramda qarindoshlarni ziyorat qilish mahalliy urf-odatdir.","collocations":"local custom / customs and traditions / custom-made"},"customer":{"id":199,"word":"Customer","uzbek":"mijoz, xaridor","type":"word","explanation":"A person who buys goods or services from a business.","izoh":"Biznesdan tovar yoki xizmat sotib oladigan shaxs.","example":"The shop offers free delivery to regular customers.","translation":"Do‘kon doimiy mijozlarga bepul yetkazib berish xizmatini taklif qiladi.","collocations":"customer service / loyal customer / customer satisfaction"},"cut":{"id":200,"word":"Cut","uzbek":"kesmoq, kamaytirmoq; qisqartirish","type":"word","explanation":"To divide something with a sharp tool, or reduce an amount.","izoh":"O‘tkir asbob bilan biror narsani bo‘lish yoki miqdorni kamaytirish.","example":"We need to cut unnecessary expenses this month.","translation":"Bu oy keraksiz xarajatlarni kamaytirishimiz kerak.","collocations":"cut costs / cut down on sugar / deep cut"},"cycle":{"id":201,"word":"Cycle","uzbek":"sikl, davr; velosiped haydamoq","type":"word","explanation":"A series of events that happen repeatedly in the same order, or to ride a bicycle.","izoh":"Bir xil tartibda takrorlanadigan hodisalar ketma-ketligi yoki velosiped haydash.","example":"The water cycle is an important part of the environment.","translation":"Suv aylanishi atrof-muhitning muhim qismidir.","collocations":"life cycle / business cycle / cycle to work"}};
